from pathlib import Path
from html.parser import HTMLParser
out=Path('/app/output')
class Parser(HTMLParser):
    def __init__(self): super().__init__(); self.hrefs=[]; self.ids=set()
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.add(d['id'])
        if tag=='a' and d.get('href'): self.hrefs.append(d['href'])
for f in ['index.html','online-courses.html','digital-downloads.html','memberships.html','coaching.html']:
    txt=out.joinpath(f).read_text(); p=Parser(); p.feed(txt); broken=[]
    for h in p.hrefs:
        if h=='#': continue
        if h.startswith('#'):
            if h[1:] not in p.ids: broken.append(h)
        elif not h.startswith('http'):
            target,_,frag=h.partition('#')
            tp=out/target
            if target and not tp.exists(): broken.append(h)
            elif frag:
                q=Parser(); q.feed(tp.read_text())
                if frag not in q.ids: broken.append(h)
    print(f, 'ids', sorted(p.ids), 'broken', broken, 'faq', txt.count('faq-item'), 'carousel', txt.count('class="carousel"'))
